<script setup>
import {ref,computed,onUnmounted,watch} from 'vue';import BaseModal from '../components/BaseModal.vue';import {state,company,api,scope,useResource,notify,changed,ask} from '../lib/workspace';
import {can,allowedApi,writable} from '../lib/workspace';import {amount,inputMoney,money,uid} from '../lib/format';
const competence=ref(state.period);
const tax=ref('icms'),show=ref(false),mode=ref('assessment'),form=ref({}),context=ref({}),error=ref(''),busy=ref(false),detail=ref(null);let baseline='';
const {data,error:loadError,reload}=useResource(async()=>{if(!state.companyId)return {documents:[],rules:[],assessments:[],adjustments:[],ledgers:[]};const [documents,rules,assessments,adjustments,ledgers]=await Promise.all([allowedApi('fiscal.documents',scope(`/documents?period=${competence.value}`)),allowedApi('fiscal.parameters',scope('/rules')),api(scope(`/assessments?period=${competence.value}`)),api(scope(`/tax-adjustments?period=${competence.value}`)),api(scope(`/tax-ledgers?period=${competence.value}`))]);return {documents,rules,assessments,adjustments,ledgers};},{documents:[],rules:[],assessments:[],adjustments:[],ledgers:[]});
watch(competence,()=>{if(!show.value)reload()});watch(()=>[state.companyId,state.period.slice(0,4)],()=>{competence.value=state.period;});
const rules=computed(()=>data.value.rules.filter(r=>r.tax.toLowerCase()===tax.value&&r.status==='validated'&&r.active&&!r.superseded_by));
async function open(type='assessment'){mode.value=type;context.value={id:state.companyId,name:company.value.name,period:competence.value};form.value={tax:tax.value,period:competence.value,idempotency_key:uid(),opening_mode:'previous',opening_reason:'',no_movement_confirmed:false,opening_credit:'0,00',source:'',responsible:'',entries:[],kind:'debit',category:'other',amount:'',reason:''};baseline=JSON.stringify(form.value);show.value=true;error.value='';state.editor={name:'Pré-apuração',companyId:state.companyId};try{const previous=await api(scope(`/tax-ledgers/previous?period=${competence.value}&tax=${tax.value}`));form.value.previous=previous;baseline=JSON.stringify(form.value);}catch(e){error.value=e.message;}}
async function close(){if(busy.value)return;if(baseline!==JSON.stringify(form.value)&&!await ask({title:'Descartar edição?',message:'A memória ainda não foi registrada.',confirmLabel:'Descartar'}))return;show.value=false;state.editor=null;}
async function save(){busy.value=true;error.value='';try{const p={...form.value,opening_credit:amount(form.value.opening_credit),amount:amount(form.value.amount),entries:form.value.entries.map(e=>({...e,base:amount(e.base)}))};const r=await api(scope(mode.value==='assessment'?'/assessments':'/tax-adjustments',context.value.id),{method:'POST',body:p});show.value=false;state.editor=null;changed();if(r.snapshot)detail.value=r;notify('Registro fiscal salvo com memória de cálculo.');}catch(e){error.value=e.message;}finally{busy.value=false;}}
async function reverse(a){const reason=await ask({title:'Estornar ajuste fiscal',message:'O ajuste será preservado no histórico e deixará de compor as próximas memórias.',inputLabel:'Justificativa',required:true,confirmLabel:'Estornar ajuste'});if(!reason)return;try{await api(scope(`/tax-adjustments/${a.id}/reverse`),{method:'POST',body:{reason,period:competence.value}});changed();}catch(e){notify(e.message,'error');}}
async function finalize(a){const reason=await ask({title:'Finalizar apuração revisada',message:'Confirme que todos os documentos, bases, não incidências, créditos e ajustes deste tributo foram revisados. A finalização protege suas bases e disponibiliza o saldo ao mês seguinte; não gera guia, título financeiro ou transmissão.',inputLabel:'Justificativa da revisão integral',required:true,confirmLabel:'Confirmar revisão e finalizar'});if(!reason)return;try{await api(scope(`/assessments/${a.id}/finalize`),{method:'POST',body:{period:competence.value,reason,coverage_reviewed:true,idempotency_key:uid()}});changed();notify('Apuração finalizada. Saldo disponível para transporte no mesmo tributo.');}catch(e){notify(e.message,'error');}}
async function undoLedger(a){const reason=await ask({title:'Reverter finalização',message:'A memória será preservada. Apurações posteriores do mesmo tributo devem ser revertidas primeiro.',inputLabel:'Justificativa',required:true,confirmLabel:'Reverter finalização'});if(!reason)return;try{await api(scope(`/tax-ledgers/${a.id}/reverse`),{method:'POST',body:{period:competence.value,reason}});changed();notify('Finalização revertida. As bases podem ser revisadas.');}catch(e){notify(e.message,'error');}}
function chooseItems(e,event){e.item_indices=Array.from(event.target.selectedOptions).map(o=>Number(o.value));}
onUnmounted(()=>{if(show.value)state.editor=null;});
</script>
<template><div class="view"><header class="view-heading"><div><div class="eyebrow">CONFERÊNCIA TRIBUTÁRIA</div><h1>Apurações e ajustes</h1><p>Regras revisadas, bases explícitas e memória por tributo.</p></div><div class="actions"><button class="button outline" v-allow="['fiscal.assessments','create']" @click="open('adjustment')">Novo ajuste</button><button class="button primary" v-allow="['fiscal.assessments','create']" @click="open()">Nova memória</button></div></header><p class="message warning">A incidência, a composição da base e a admissibilidade do crédito dependem de revisão fiscal. Não há compensação entre tributos nem transmissão de obrigações.</p><p v-if="loadError" class="message error">{{loadError}}</p><label class="operation-month">Competência da apuração<select v-model="competence" :disabled="!!state.editor"><option v-for="m in 12" :value="state.period.slice(0,4)+'-'+String(m).padStart(2,'0')">{{String(m).padStart(2,'0')}}/{{state.period.slice(0,4)}} · {{state.yearLocks.fiscal?.[state.period.slice(0,4)+'-'+String(m).padStart(2,'0')]?.closed?'Fechada':'Aberta'}}</option></select></label><select v-model="tax" aria-label="Tributo da pré-apuração"><option v-for="t in ['icms','ipi','iss','pis','cofins','ibs','cbs']" :key="t" :value="t">{{t.toUpperCase()}}</option></select><section class="panel"><div class="table-scroll"><table><thead><tr><th>Memória</th><th>Tributo</th><th>Débitos</th><th>Créditos</th><th>A recolher</th><th>Crédito a transportar</th><th>Conferência</th><th></th></tr></thead><tbody><tr v-for="a in data.assessments.filter(a=>a.tax===tax)" :key="a.id"><td>#{{a.id}} · {{a.created_at}}</td><td>{{a.tax.toUpperCase()}}</td><td>{{money(a.snapshot.debit_cents)}}</td><td>{{money(a.snapshot.credit_cents)}}</td><td>{{money(a.snapshot.payable_cents)}}</td><td>{{money(a.snapshot.carry_credit_cents)}}</td><td><span class="badge" :class="a.stale?'warning':'success'">{{a.stale?'Origem alterada — refazer':'Origem preservada'}}</span></td><td><button class="button small" @click="detail=a">Ver memória</button><button v-if="!a.stale&&!data.ledgers.some(l=>!l.reversed_at&&l.tax===a.tax)" v-allow="['fiscal.assessments','book']" class="button small outline" @click="finalize(a)">Finalizar</button></td></tr></tbody></table></div></section><section class="panel"><div class="panel-heading"><h2>Apurações finalizadas</h2></div><div v-for="l in data.ledgers.filter(l=>l.tax===tax)" :key="l.id" class="assessment-entry"><strong>#{{l.id}} · {{l.tax.toUpperCase()}} · {{l.reversed_at?'Revertida':l.stale?'Origem alterada — revisar':'Finalizada'}}</strong><p>Crédito anterior {{money(l.opening_credit_cents)}} · a recolher {{money(l.payable_cents)}} · a transportar {{money(l.carry_credit_cents)}}</p><p>{{l.reason}} · {{l.created_by}} · {{l.created_at}}</p><div class="actions"><a v-allow="['fiscal.assessments','print']" class="button small" :href="`/api${scope(`/tax-ledgers/${l.id}/report`)}?format=pdf&purpose=print`" target="_blank" rel="noopener">Prévia / imprimir</a><a v-allow="['fiscal.assessments','export']" class="button small" :href="`/api${scope(`/tax-ledgers/${l.id}/report`)}?format=pdf`" download>PDF da memória</a><a v-allow="['fiscal.assessments','export']" class="button small" :href="`/api${scope(`/tax-ledgers/${l.id}/report`)}?format=xlsx`" download>Excel da memória</a><button v-if="!l.reversed_at" v-allow="['fiscal.assessments','reverse']" class="button small" @click="undoLedger(l)">Reverter finalização</button></div></div><p v-if="!data.ledgers.some(l=>l.tax===tax)" class="report-note">Nenhuma finalização deste tributo na competência.</p></section><h2>Ajustes da competência</h2><section class="panel"><table><thead><tr><th>Tributo</th><th>Natureza</th><th>Valor</th><th>Motivo / fonte</th><th></th></tr></thead><tbody><tr v-for="a in data.adjustments.filter(a=>a.tax===tax)" :key="a.id"><td>{{a.tax.toUpperCase()}}</td><td>{{a.kind==='debit'?'Débito':'Crédito'}}</td><td>{{money(a.amount_cents)}}</td><td>{{a.reason}} · {{a.source}}</td><td><span v-if="a.reversed_at">Estornado</span><button v-else class="button small" v-allow="['fiscal.assessments','reverse']" @click="reverse(a)">Estornar</button></td></tr></tbody></table></section>
<BaseModal v-if="show" :title="mode==='assessment'?'Nova memória de pré-apuração':'Novo ajuste fiscal'" :subtitle="`${context.name} · ${context.period} · ${tax.toUpperCase()}`" wide @close="close"><p v-if="error" class="message error" role="alert">{{error}}</p><form id="assessment-form" @submit.prevent="save"><div class="form-grid"><label class="span-2">Fundamentação / fonte normativa *<textarea v-model="form.source" required/></label><template v-if="mode==='assessment'"><label>Responsável pela conferência *<input v-model="form.responsible" required/></label><label>Origem do saldo anterior<select v-model="form.opening_mode"><option value="previous">Transportar apuração do mês anterior</option><option value="manual">Implantação / saldo conferido manualmente</option></select></label><p v-if="form.opening_mode==='previous'" class="span-2">{{form.previous?.period}} · saldo do mesmo tributo: {{money(form.previous?.carry_credit_cents||0)}} · {{form.previous?.ledger_id?'Apuração #'+form.previous.ledger_id:'Sem finalização anterior; saldo zero'}} {{form.previous?.stale?'· Origem alterada: revisar':''}}</p><template v-else><label>Saldo credor anterior deste tributo<input v-model="form.opening_credit" inputmode="decimal"/></label><label>Fundamento do saldo manual<input v-model="form.opening_reason" required/></label></template></template><template v-else><label>Categoria do ajuste<select v-model="form.category" @change="form.kind=['debit','reverse_credit'].includes(form.category)?'debit':['credit','reverse_debit'].includes(form.category)?'credit':form.kind"><option value="other">Outro ajuste conferido</option><option value="debit">Débito</option><option value="credit">Crédito</option><option value="reverse_debit">Estorno de débito</option><option value="reverse_credit">Estorno de crédito</option></select></label><label>Natureza<select v-model="form.kind"><option value="debit">Débito</option><option value="credit">Crédito</option></select></label><label>Valor (R$) *<input v-model="form.amount" required/></label><label class="span-2">Justificativa *<input v-model="form.reason" required/></label></template></div><template v-if="mode==='assessment'"><p v-if="!rules.length" class="message warning">Cadastre e revise uma regra deste tributo em Parâmetros antes de apurar.</p><div v-for="(e,i) in form.entries" :key="i" class="assessment-entry form-grid three"><label>Documento escriturado<select v-model.number="e.document_id" required @change="e.base=inputMoney(data.documents.find(d=>d.id===e.document_id)?.total_cents)"><option value="">Selecione</option><option v-for="d in data.documents.filter(d=>d.status==='booked')" :key="d.id" :value="d.id">{{d.number}} · {{d.partner_name}}</option></select></label><label>Regra revisada<select v-model.number="e.rule_id" required><option value="">Selecione</option><option v-for="r in rules" :key="r.id" :value="r.id">{{r.name}} · {{r.rate}}% · {{r.source}}</option></select></label><label>Natureza<select v-model="e.effect"><option value="debit">Débito</option><option value="credit">Crédito conferido</option></select></label><label class="span-3">Itens abrangidos (opcional; sem seleção abrange o documento)<select multiple :value="e.item_indices||[]" @change="chooseItems(e,$event)"><option v-for="(item,index) in data.documents.find(d=>d.id===e.document_id)?.items||[]" :key="index" :value="index">{{index+1}} · {{item.description}} · NCM {{item.ncm}} · {{item.total}}</option></select></label><label>Base conferida (R$)<input v-model="e.base" required/></label><label class="span-2">Fundamento da base / direito ao crédito<input v-model="e.reason" required/></label><button type="button" class="text-button" @click="form.entries.splice(i,1)">Remover base</button></div><button type="button" class="button outline" @click="form.no_movement_confirmed=false;form.entries.push({document_id:'',rule_id:'',effect:'debit',base:'',reason:'',item_indices:[]})">Adicionar base conferida</button><label v-if="!form.entries.length" class="check-label"><input v-model="form.no_movement_confirmed" type="checkbox"/>Confirmei a ausência de bases neste cenário; apurar somente ajustes e saldo anterior.</label></template></form><template #footer><button class="button" @click="close" :disabled="busy">Cancelar</button><button class="button primary" form="assessment-form" :disabled="busy">Registrar {{mode==='assessment'?'memória':'ajuste'}}</button></template></BaseModal>
<BaseModal v-if="detail" title="Memória de cálculo" wide @close="detail=null"><p>{{detail.source}} · Conferência: {{detail.responsible}}</p><p>{{detail.snapshot.scope_note}}</p><p>Saldo anterior: {{money(detail.snapshot.opening_credit_cents)}} · a recolher: {{money(detail.snapshot.payable_cents)}} · a transportar: {{money(detail.snapshot.carry_credit_cents)}}</p><div class="table-scroll"><table><thead><tr><th>Documento / versão</th><th>Regra / versão</th><th>Base</th><th>Alíquota</th><th>Resultado</th><th>Natureza</th><th>Fundamento</th></tr></thead><tbody><tr v-for="(e,i) in detail.snapshot.entries" :key="i"><td>{{e.document_number}} · v{{e.document_version}}</td><td>#{{e.rule_id}} · v{{e.rule_version}}</td><td>{{money(e.base_cents)}}</td><td>{{e.rate}}%</td><td>{{money(e.result_cents)}}</td><td>{{e.effect==='debit'?'Débito':'Crédito'}}</td><td>{{e.reason}} · {{e.source}}</td></tr></tbody></table></div><p>Arredondamento: metade para cima, em centavos, por base conferida.</p><small class="wrap-anywhere">Identificador da memória: {{detail.fingerprint}}</small><template #footer><button class="button" @click="detail=null">Fechar</button></template></BaseModal></div></template>
